const input = $input.first().json;

// 1) LLM 결과 텍스트 후보
const rawText = (
input?.text ||
input?.summaryText ||
input?.content?.parts?.[0]?.text ||
''
).trim();

// 2) JSON 파싱 유틸 (```json ... ``` 제거 포함)
function parseJsonLoose(str) {
if (!str) return null;

const cleaned = str
.replace(/^```json\s*/i, '')
.replace(/^```\s*/i, '')
.replace(/\s*```$/i, '')
.trim();

try {
return JSON.parse(cleaned);
} catch {
// 문자열 내 첫 JSON 객체 구간을 찾아 재시도
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start !== -1 && end !== -1 && end > start) {
const slice = cleaned.slice(start, end + 1);
try { return JSON.parse(slice); } catch {}
}
return null;
}
}

// 3) 파싱 시도
const parsed = parseJsonLoose(rawText) || {};

// 4) summaryText 구성
let summaryText =
(parsed.summaryText && String(parsed.summaryText).trim()) ||
rawText;

// 길이 가드
const MAX_LEN = 520;
if (summaryText.length > MAX_LEN) {
summaryText = summaryText.slice(0, MAX_LEN - 20) + '\n\n...(생략)';
}

// 5) items 구성 (parsed.items 우선, 없으면 news_list fallback)
let items = [];
if (Array.isArray(parsed.items)) {
items = parsed.items;
} else if (Array.isArray(input.news_list)) {
items = input.news_list.map(n => ({
title: (n.title || '').trim(),
url: (n.link || n.url || '').trim(),
}));
}

// 정규화 + dedupe
const seen = new Set();
items = items
.map(it => ({
title: (it?.title || '').trim(),
url: (it?.url || it?.link || '').trim(),
}))
.filter(it => it.title && /^https?:\/\//.test(it.url))
.filter(it => {
if (seen.has(it.url)) return false;
seen.add(it.url);
return true;
})
.slice(0, 4);

// 6) 최종 응답 스키마
return [{
json: {
ok: true,
source: 'geeknews',
generatedAt: new Date().toISOString(),
summaryText,
items,
}
}];
